package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;
public class ApplicationChecklistActivity extends Activity{private final String[] items={"Organisation constituée et admissible au Québec","Projet basé sur une des 5 normes reconnues","Mise à niveau concrète d’une base de données","Durée maximale de 12 mois","Soumission d’un fournisseur ou capacité interne démontrée","Description complète du projet","Budget détaillé","Équipe et sous-traitants documentés","Plan de gestion des données","Documents financiers et corporatifs requis","Dépenses prévues après l’annonce de l’aide, lorsque requis","Site Web ou API externe ne constitue pas la majorité du projet","Mesures de résultats prévues","Modalités de partage / données ouvertes évaluées"};@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);SharedPreferences p=getSharedPreferences("application_checklist",0);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Liste de contrôle du dossier",27,true));r.addView(Ui.text(this,"Cette liste aide à préparer le dossier; elle ne remplace pas les formulaires ni l’évaluation du Ministère.",13,false));for(int i=0;i<items.length;i++){final int n=i;CheckBox c=new CheckBox(this);c.setText(items[i]);c.setTextSize(15);c.setChecked(p.getBoolean("i"+i,false));c.setOnCheckedChangeListener((v,x)->p.edit().putBoolean("i"+n,x).apply());r.addView(c);}setContentView(Ui.wrap(this,r));}}
